    "challenge_index": 5,
    "question_text": "TYPOLOGY LINKS:\nIn 1 Corinthians 10:4, Paul interprets the wilderness journey of Israel, stating: \"For they drank from the spiritual Rock that followed them, and the Rock was Christ.\" In Exodus 17 and Numbers 20, what difference between Moses' two encounters with the rock illustrates Christ being struck once for all?",
